"use client";

import { Center, Line, Text, useGLTF, useTexture } from "@react-three/drei";
import { useFrame } from "@react-three/fiber";
import {
  Box3,
  CatmullRomCurve3,
  Color,
  Group,
  MathUtils,
  Mesh,
  MeshPhysicalMaterial,
  RepeatWrapping,
  SRGBColorSpace,
  Vector3,
} from "three";
import { useMemo, useRef, useState } from "react";
import { assetPath } from "@/lib/asset-path";
import { chapters, makmaSystems } from "@/lib/narrative";
import { useExperience } from "@/store/experience";

const FLOOR_Y = -0.78;
const HALL_HALF = 5.4;
const ARCH_TOP = 4.6;

function normalizedClone(scene: Group, targetHeight: number) {
  const clone = scene.clone(true);
  clone.traverse((object) => {
    if ((object as Mesh).isMesh) {
      const mesh = object as Mesh;
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      const material = mesh.material;
      if (material && !Array.isArray(material) && "envMapIntensity" in material) {
        (material as MeshPhysicalMaterial).envMapIntensity = 0.95;
      }
    }
  });
  const box = new Box3().setFromObject(clone);
  const size = box.getSize(new Vector3());
  const center = box.getCenter(new Vector3());
  const scale = targetHeight / Math.max(size.y, 0.001);
  clone.position.sub(center);
  clone.scale.setScalar(scale);
  return clone;
}

function ArtifactModel({
  id,
  file,
  position,
  targetHeight,
  rotation = [0, 0, 0],
  label,
  note,
}: {
  id: string;
  file: string;
  position: [number, number, number];
  targetHeight: number;
  rotation?: [number, number, number];
  label: string;
  note: string;
}) {
  const { scene } = useGLTF(assetPath(`/assets/models/${file}.glb`)) as unknown as { scene: Group };
  const object = useMemo(() => normalizedClone(scene, targetHeight), [scene, targetHeight]);
  const inspect = useExperience((state) => state.inspect);
  const group = useRef<Group>(null);
  const [hovered, setHovered] = useState(false);

  useFrame((_, delta) => {
    if (!group.current) return;
    const target = hovered ? 1.035 : 1;
    const scale = MathUtils.damp(group.current.scale.x, target, 9, delta);
    group.current.scale.setScalar(scale);
  });

  return (
    <group
      ref={group}
      position={position}
      rotation={rotation}
      onClick={(event) => {
        event.stopPropagation();
        inspect(id);
      }}
      onPointerOver={(event) => {
        event.stopPropagation();
        setHovered(true);
        document.body.style.cursor = "pointer";
      }}
      onPointerOut={() => {
        setHovered(false);
        document.body.style.cursor = "";
      }}
    >
      <primitive object={object} />
      <group position={[0, -targetHeight * 0.54, 0]}>
        <mesh position={[0, -0.08, 0]} receiveShadow>
          <cylinderGeometry args={[0.72, 0.78, 0.14, 48]} />
          <meshPhysicalMaterial color="#171714" metalness={0.62} roughness={0.34} />
        </mesh>
        <Text position={[0, -0.26, 0.02]} fontSize={0.075} color={hovered ? "#e5c18d" : "#96856f"}>
          {label}
        </Text>
        <Text position={[0, -0.39, 0.02]} fontSize={0.042} color="#6b655d">
          {note}
        </Text>
      </group>
    </group>
  );
}

function VaultBay({ z, index }: { z: number; index: number }) {
  const chapter = useExperience((state) => state.chapter);
  const activeIndex = chapters.findIndex((item) => item.id === chapter);
  const glow = Math.max(0, 1 - Math.abs(index - activeIndex) * 0.22);

  return (
    <group position={[0, 0, z]}>
      <mesh position={[-HALL_HALF, 1.86, 0]} castShadow receiveShadow>
        <cylinderGeometry args={[0.18, 0.24, 5.2, 18]} />
        <meshStandardMaterial color="#504940" roughness={0.92} />
      </mesh>
      <mesh position={[HALL_HALF, 1.86, 0]} castShadow receiveShadow>
        <cylinderGeometry args={[0.18, 0.24, 5.2, 18]} />
        <meshStandardMaterial color="#504940" roughness={0.92} />
      </mesh>
      <mesh position={[0, ARCH_TOP - 0.28, 0]} rotation={[0, 0, 0]} castShadow receiveShadow>
        <torusGeometry args={[HALL_HALF, 0.18, 16, 96, Math.PI]} />
        <meshStandardMaterial
          color={glow > 0.35 ? "#756653" : "#514a41"}
          roughness={0.84}
          metalness={0.03}
          emissive={new Color("#2f1b0d")}
          emissiveIntensity={glow * 0.18}
        />
      </mesh>
      <spotLight
        position={[0, ARCH_TOP - 0.35, 0.7]}
        target-position={[0, 0.2, -1.6]}
        intensity={0.7 + glow * 2.2}
        angle={0.46}
        penumbra={0.9}
        distance={9}
        color={glow > 0.25 ? "#e0b77d" : "#a6b1ad"}
        castShadow={glow > 0.55}
      />
    </group>
  );
}

function ArchiveArchitecture() {
  const floor = useTexture([
    assetPath("/assets/materials/hangar_concrete_floor/diffuse.jpg"),
    assetPath("/assets/materials/hangar_concrete_floor/normal.jpg"),
    assetPath("/assets/materials/hangar_concrete_floor/roughness.jpg"),
  ]);
  const [base, normal, rough] = floor;
  base.colorSpace = SRGBColorSpace;
  for (const texture of floor) {
    texture.wrapS = texture.wrapT = RepeatWrapping;
    texture.repeat.set(3.2, 28);
  }

  const bayZ = useMemo(() => Array.from({ length: 16 }, (_, index) => 5 - index * 7.7), []);

  return (
    <group>
      <mesh position={[0, FLOOR_Y, -54]} rotation={[-Math.PI / 2, 0, 0]} receiveShadow>
        <planeGeometry args={[12.4, 126]} />
        <meshStandardMaterial map={base} normalMap={normal} roughnessMap={rough} roughness={0.9} />
      </mesh>

      <mesh position={[-6.25, 2.15, -54]} receiveShadow>
        <boxGeometry args={[0.42, 6.4, 126]} />
        <meshStandardMaterial color="#272622" roughness={0.97} />
      </mesh>
      <mesh position={[6.25, 2.15, -54]} receiveShadow>
        <boxGeometry args={[0.42, 6.4, 126]} />
        <meshStandardMaterial color="#272622" roughness={0.97} />
      </mesh>

      {bayZ.map((z, index) => (
        <VaultBay key={z} z={z} index={Math.min(index, chapters.length - 1)} />
      ))}

      <mesh position={[0, 5.1, -54]} rotation={[Math.PI / 2, 0, 0]} receiveShadow>
        <planeGeometry args={[12.5, 126]} />
        <meshStandardMaterial color="#11110f" roughness={0.98} side={2} />
      </mesh>
    </group>
  );
}

function SignalInlay() {
  const points = useMemo(
    () =>
      new CatmullRomCurve3([
        new Vector3(-0.12, FLOOR_Y + 0.025, 7),
        new Vector3(0.18, FLOOR_Y + 0.025, -8),
        new Vector3(-0.3, FLOOR_Y + 0.025, -24),
        new Vector3(0.35, FLOOR_Y + 0.025, -44),
        new Vector3(-0.1, FLOOR_Y + 0.025, -66),
        new Vector3(0.28, FLOOR_Y + 0.025, -88),
        new Vector3(0, FLOOR_Y + 0.025, -116),
      ]),
    []
  );
  const progress = useExperience((state) => state.progress);
  const marker = useRef<Group>(null);

  useFrame((_, delta) => {
    if (!marker.current) return;
    const p = points.getPointAt(MathUtils.clamp(progress, 0, 1));
    marker.current.position.x = MathUtils.damp(marker.current.position.x, p.x, 10, delta);
    marker.current.position.y = p.y + 0.06;
    marker.current.position.z = MathUtils.damp(marker.current.position.z, p.z, 10, delta);
  });

  const samples = useMemo(() => points.getPoints(180), [points]);

  return (
    <>
      <Line points={samples} color="#7b5a32" lineWidth={1.5} transparent opacity={0.65} />
      <group ref={marker} position={[0, FLOOR_Y + 0.08, 7]}>
        <mesh>
          <sphereGeometry args={[0.055, 20, 20]} />
          <meshBasicMaterial color="#ffd08a" />
        </mesh>
        <pointLight intensity={3.5} distance={3.2} color="#e7a454" />
      </group>
    </>
  );
}

function TimelineMarkers() {
  const zPositions = [5, -8, -19, -30, -39, -47, -55, -63, -72, -80, -88, -96, -106, -116];

  return (
    <group>
      {chapters.map((chapter, index) => (
        <group key={chapter.id} position={[-4.9, FLOOR_Y + 0.035, zPositions[index]]}>
          <mesh rotation={[-Math.PI / 2, 0, 0]}>
            <planeGeometry args={[1.5, 0.42]} />
            <meshPhysicalMaterial color="#171612" metalness={0.58} roughness={0.34} />
          </mesh>
          <Text
            position={[0, 0.015, 0]}
            rotation={[-Math.PI / 2, 0, 0]}
            fontSize={0.075}
            color="#9f896b"
            anchorX="center"
          >
            {chapter.year}
          </Text>
        </group>
      ))}
    </group>
  );
}

function KnowledgeSculpture() {
  const root = useRef<Group>(null);
  const progress = useExperience((state) => state.progress);
  const nodes = useMemo(
    () =>
      Array.from({ length: 18 }, (_, index) => {
        const angle = index * 2.399;
        const radius = 0.9 + (index % 5) * 0.26;
        return new Vector3(Math.cos(angle) * radius, (index % 6) * 0.34 - 0.8, Math.sin(angle) * radius);
      }),
    []
  );

  useFrame((_, delta) => {
    if (!root.current) return;
    root.current.rotation.y += delta * (0.035 + Math.max(0, progress - 0.52) * 0.06);
  });

  return (
    <group ref={root} position={[2.6, 1.15, -72]}>
      {nodes.map((node, index) => (
        <group key={index} position={node}>
          <mesh>
            <sphereGeometry args={[index % 4 === 0 ? 0.11 : 0.065, 18, 18]} />
            <meshPhysicalMaterial
              color={index % 3 === 0 ? "#bc8d54" : "#6f8682"}
              emissive={index % 3 === 0 ? "#3b1d08" : "#102625"}
              emissiveIntensity={0.7}
              metalness={0.55}
              roughness={0.28}
            />
          </mesh>
          {index > 0 ? (
            <Line points={[new Vector3(), nodes[Math.max(0, index - 1)].clone().sub(node)]} color="#8d7657" transparent opacity={0.34} lineWidth={0.8} />
          ) : null}
        </group>
      ))}
      <Text position={[0, -1.55, 0]} fontSize={0.07} color="#8f806d">
        INFORMATION → KNOWLEDGE
      </Text>
    </group>
  );
}

function ProjectRotunda() {
  const inspect = useExperience((state) => state.inspect);

  return (
    <group position={[0, 0.3, -106]}>
      <mesh position={[0, FLOOR_Y - 0.02, 0]} rotation={[-Math.PI / 2, 0, 0]} receiveShadow>
        <circleGeometry args={[8.1, 96]} />
        <meshPhysicalMaterial color="#1b1b18" roughness={0.46} metalness={0.18} clearcoat={0.12} />
      </mesh>

      {makmaSystems.map(([domain, system], index) => {
        const angle = (index / makmaSystems.length) * Math.PI * 2;
