            </mesh>
            <Text position={[0, -0.9, 0.16]} fontSize={0.075} color="#d0c0a8" maxWidth={1.9} textAlign="center">
              {system}
            </Text>
            <Text position={[0, -1.08, 0.16]} fontSize={0.042} color="#7d6f5c">
