"use client";

import { Canvas } from "@react-three/fiber";
import { PerformanceMonitor, Preload } from "@react-three/drei";
import { Suspense, useMemo } from "react";
import { ACESFilmicToneMapping, PCFSoftShadowMap, SRGBColorSpace } from "three";
import { useExperience } from "@/store/experience";
import { QUALITY } from "@/lib/quality";
import { World } from "./World";
import { CameraRig } from "./CameraRig";
import { PostFX } from "./PostFX";

export function ExperienceCanvas() {
  const automated =
    typeof window !== "undefined" &&
    new URLSearchParams(window.location.search).get("automation") === "1";
  const quality = useExperience((state) => state.quality);
  const setQuality = useExperience((state) => state.setQuality);
  const profile = QUALITY[quality];

  const canvasProps = useMemo(
    () => ({
      shadows: !automated,
      dpr: automated ? ([0.6, 0.8] as [number, number]) : profile.dpr,
      gl: {
        antialias: !automated && quality !== "safe",
        powerPreference: "high-performance" as const,
        alpha: false,
      },
      camera: { fov: 46, near: 0.08, far: 180, position: [0, 1.65, 8.5] as [number, number, number] },
    }),
    [profile.dpr, quality]
  );

  return (
    <div className="experience-canvas" aria-hidden="true">
      <Canvas
        {...canvasProps}
        onCreated={({ gl }) => {
          gl.toneMapping = ACESFilmicToneMapping;
          gl.outputColorSpace = SRGBColorSpace;
          gl.shadowMap.type = PCFSoftShadowMap;
        }}
      >
        {!automated ? (
          <PerformanceMonitor
            flipflops={3}
            factor={1}
            onIncline={() =>
              setQuality(quality === "balanced" ? "high" : quality === "high" ? "ultra" : quality)
            }
            onDecline={() =>
              setQuality(quality === "ultra" ? "high" : quality === "high" ? "balanced" : "safe")
            }
          />
        ) : null}
        <Suspense fallback={null}>
          <World />
          <CameraRig />
          {!automated ? <PostFX /> : null}
          <Preload all />
        </Suspense>
      </Canvas>
    </div>
  );
}

