"use client";

import { useFrame } from "@react-three/fiber";
import { CatmullRomCurve3, MathUtils, Vector3 } from "three";
import { useMemo, useRef } from "react";
import { chapters } from "@/lib/narrative";
import { useExperience } from "@/store/experience";

const CAMERA_POINTS = [
  [0.0, 1.55, 9.4],
  [-0.35, 1.62, -4],
  [0.45, 1.72, -15],
  [-0.55, 1.75, -27],
  [0.55, 1.72, -39],
  [-0.38, 1.76, -53],
  [0.55, 1.82, -68],
  [-0.45, 1.82, -82],
  [0.25, 2.0, -95],
  [0.0, 2.35, -106],
  [0.0, 2.65, -118],
] as const;

export function CameraRig() {
  const progress=useExperience((state)=>state.progress);
  const velocity=useExperience((state)=>state.velocity);
  const setChapter=useExperience((state)=>state.setChapter);
  const smoothProgress=useRef(0);
  const look=useRef(new Vector3(0,1.55,0));
  const bank=useRef(0);

  const path=useMemo(
    ()=>new CatmullRomCurve3(
      CAMERA_POINTS.map(([x,y,z])=>new Vector3(x,y,z)),
      false,
      "catmullrom",
      0.48
    ),
    []
  );

  useFrame(({camera,pointer},delta)=>{
    smoothProgress.current=MathUtils.damp(smoothProgress.current,progress,6.8,delta);
    const t=MathUtils.clamp(smoothProgress.current,0,1);
    const position=path.getPointAt(t);
    const lookAhead=0.012+Math.min(Math.abs(velocity)*0.000045,0.006);
    const ahead=path.getPointAt(Math.min(1,t+lookAhead));

    const pointerX=pointer.x*0.085;
    const pointerY=pointer.y*0.045;

    camera.position.x=MathUtils.damp(camera.position.x,position.x+pointerX,7.2,delta);
    camera.position.y=MathUtils.damp(camera.position.y,position.y+pointerY,7.2,delta);
    camera.position.z=MathUtils.damp(camera.position.z,position.z,8.8,delta);

    look.current.x=MathUtils.damp(look.current.x,ahead.x+pointer.x*0.11,8.2,delta);
    look.current.y=MathUtils.damp(look.current.y,ahead.y+pointer.y*0.055,8.2,delta);
    look.current.z=MathUtils.damp(look.current.z,ahead.z-2.5,9.5,delta);
    camera.lookAt(look.current);

    const targetBank=MathUtils.clamp(velocity*0.000015,-0.012,0.012);
    bank.current=MathUtils.damp(bank.current,targetBank,6,delta);
    camera.rotation.z+=bank.current;

    const index=Math.min(chapters.length-1,Math.round(t*(chapters.length-1)));
    setChapter(chapters[index].id);
  });

  return null;
}

