"use client";

import { useFrame, useThree } from "@react-three/fiber";
import { Color, FogExp2, MathUtils } from "three";
import { chapters } from "@/lib/narrative";
import { useExperience } from "@/store/experience";

const palette = {
  dark: ["#090806", "#15110d", 0.020],
  workshop: ["#15110c", "#21180f", 0.018],
  crossing: ["#121515", "#202524", 0.021],
  lab: ["#171816", "#232521", 0.016],
  industry: ["#111310", "#1d201b", 0.017],
  knowledge: ["#0d1110", "#19201d", 0.019],
  clinical: ["#171a18", "#262b27", 0.015],
  validation: ["#13100b", "#241a0f", 0.017],
  makma: ["#090b09", "#111611", 0.015],
  horizon: ["#2b2922", "#5d5141", 0.008],
} as const;

export function Atmosphere() {
  const chapterId=useExperience((state)=>state.chapter);
  const { scene }=useThree();

  useFrame((_,delta)=>{
    const chapter=chapters.find((item)=>item.id===chapterId) ?? chapters[0];
    const [bg,fog,density]=palette[chapter.environment];
    const bgColor=new Color(bg);
    const fogColor=new Color(fog);

    if(!(scene.background instanceof Color)) scene.background=new Color(bg);
    scene.background.lerp(bgColor,1-Math.exp(-2.2*delta));

    if(!(scene.fog instanceof FogExp2)) scene.fog=new FogExp2(fog,density);
    scene.fog.color.lerp(fogColor,1-Math.exp(-2.0*delta));
    scene.fog.density=MathUtils.damp(scene.fog.density,density,2.8,delta);
  });

  return null;
}

