"use client";

import { Text } from "@react-three/drei";
import { useFrame } from "@react-three/fiber";
import { useMemo, useRef } from "react";
import { Group, MathUtils } from "three";
import { chapters, type CapabilityId } from "@/lib/narrative";
import { useExperience } from "@/store/experience";

const moduleOrder: CapabilityId[] = [
  "compute","data","software","math","ml","responsible-ai","distributed-compute",
  "analytics","language","governance","decision","knowledge","retrieval","evaluation",
  "engineering","evidence","operations","orchestration"
];

function gainedUntil(chapterId: string) {
  const end = chapters.findIndex((chapter) => chapter.id === chapterId);
  const set = new Set<CapabilityId>();
  chapters.slice(0, Math.max(0, end + 1)).forEach((chapter) => {
    chapter.capabilities.forEach((capability) => set.add(capability));
  });
  return set;
}

export function EvolvingMachine() {
  const chapter = useExperience((state) => state.chapter);
  const progress = useExperience((state) => state.progress);
  const root = useRef<Group>(null);
  const gained = useMemo(() => gainedUntil(chapter), [chapter]);

  useFrame((_, delta) => {
    if (!root.current) return;
    root.current.rotation.y += delta * 0.04;
    root.current.position.y=MathUtils.damp(root.current.position.y,chapter==="future"?1.85:1.25,4,delta);
    root.current.position.z=MathUtils.damp(root.current.position.z,4.6-progress*119,6.5,delta);
    root.current.position.x=MathUtils.damp(root.current.position.x,1.85+Math.sin(progress*Math.PI*7)*0.12,5,delta);
    const scale=0.52+progress*0.32;
    root.current.scale.setScalar(MathUtils.damp(root.current.scale.x,scale,5,delta));
  });

  return (
    <group ref={root} position={[1.85,1.25,4.6]} scale={0.52}>
      <mesh castShadow receiveShadow>
        <cylinderGeometry args={[1.4, 1.65, 0.42, 64]} />
        <meshPhysicalMaterial color="#24231f" roughness={0.32} metalness={0.82} clearcoat={0.28} />
      </mesh>

      <mesh position={[0, 0.62, 0]} castShadow>
        <cylinderGeometry args={[0.72, 0.92, 1.05, 48]} />
        <meshPhysicalMaterial color="#111412" roughness={0.22} metalness={0.92} clearcoat={0.5} />
      </mesh>

      {moduleOrder.map((id, index) => {
        const active = gained.has(id);
        const angle = (index / moduleOrder.length) * Math.PI * 2;
        const radius = 1.9 + (index % 3) * 0.18;
        return (
          <group
            key={id}
            position={[Math.cos(angle) * radius, 0.48 + (index % 2) * 0.2, Math.sin(angle) * radius]}
            rotation={[0, -angle + Math.PI / 2, 0]}
          >
            <mesh castShadow={active}>
              <boxGeometry args={[0.48, 0.34, 0.72]} />
              <meshPhysicalMaterial
                color={active ? "#6f5638" : "#1b1c19"}
                emissive={active ? "#2e1705" : "#000000"}
                emissiveIntensity={active ? 0.75 : 0}
                roughness={active ? 0.28 : 0.7}
                metalness={active ? 0.75 : 0.18}
              />
            </mesh>
            <mesh position={[0, 0.04, 0.371]}>
              <planeGeometry args={[0.28, 0.06]} />
              <meshBasicMaterial color={active ? "#e3b46e" : "#34332f"} />
            </mesh>
          </group>
        );
      })}

      <Text position={[0, 1.55, 0]} fontSize={0.16} color="#b9aa95" anchorX="center">
        EVOLVING SYSTEM
      </Text>
    </group>
  );
}

